529	/// Calls the run's observer, if any, and reports whether the call panicked. The observer is caller code: a panic in
530	/// it is caught so it can neither unwind the scheduler (losing the record and dropping running steps) nor stop the
531	/// run. The caller counts it in [`RunRecord::observer_panics`].
532	fn observe(opts: &ExecOptions, call: impl FnOnce(&dyn StepObserver)) -> bool {
533	    let Some(observer) = opts.observer.as_deref() else { return false };
534	    // AssertUnwindSafe: after a caught panic the scheduler only reads its own state, which the observer cannot
535	    // touch; whatever state the observer itself left half-updated is its own.
536	    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| call(observer))).is_err()
