580	/// One precheck under the attempt's time limit, racing cancellation plus the grace period like an attempt.
581	async fn precheck_once(
582	    step: &dyn Step,
583	    ctx: &StepContext,
584	    limit: Duration,
585	    token: &CancellationToken,
586	    grace: Duration,
587	) -> Checked {
588	    let check = tokio::time::timeout(limit, step.precheck(ctx));
589	    let interrupted = async {
590	        token.cancelled().await;
591	        tokio::time::sleep(grace).await;
592	    };
593	    let result = tokio::select! {
594	        biased;
595	        result = check => result.unwrap_or(Err(ExecutionError::Timeout { elapsed_ms: millis(limit) })),
596	        () = interrupted => return Checked::Unknown("the precheck was still running after cancellation".to_string()),
597	    };
598	    match result {
599	        Ok(Precheck::Applied) => Checked::Applied,
600	        Ok(Precheck::NotApplied) => Checked::NotApplied,
601	        Ok(_) => Checked::Unknown("the precheck answered unknown".to_string()),
602	        Err(err) if err.replay_class() == ReplayClass::Refused => Checked::Refused(err),
603	        Err(err) => Checked::Unknown(format!("the precheck failed: {err}")),
604	    }
605	}
