607	/// Reports a failed step's last error to its breaker, if it holds an admission.
608	///
609	/// Healthy: a client error (the downstream answered and rejected this request, so it is up) and
610	/// [`ExecutionError::refused`] (the step rejected the work before any call, so it says nothing about the downstream).
611	/// Neither: cancellation, interruption and a passed deadline. Failure: everything else, including
612	/// [`ExecutionError::rejected`] (a dependency turned the request away) and [`ExecutionError::failed`] (the step can't
613	/// say what happened).
614	fn report_failure(guard: Option<AdmissionGuard>, err: &ExecutionError) {
615	    if let Some(guard) = guard {
616	        match err.innermost() {
617	            // Cancellation and a passed deadline say nothing about the downstream's health: release a probe, report
618	            // nothing.
619	            ExecutionError::Cancelled | ExecutionError::Interrupted { .. } | ExecutionError::DeadlinePassed { .. } => {}
620	            // The downstream answered and rejected the request itself: it is up, so this is not a failure.
621	            ExecutionError::Http { status, .. } if is_client_error(*status) => guard.complete(true),
622	            // The step refused the work itself, before reaching the downstream.
623	            ExecutionError::Failed { retryable: false, effect: Effect::NotApplied, .. } => guard.complete(true),
624	            _ => guard.complete(false),
625	        }
626	    }
627	}
