630	async fn attempt_once(
631	    step: &dyn Step,
632	    ctx: &StepContext,
633	    limit: Duration,
634	    token: &CancellationToken,
635	    grace: Duration,
636	) -> Result<(), ExecutionError> {
637	    let start = Instant::now();
638	    let attempt = tokio::time::timeout(limit, step.run(ctx));
639	    let interrupted = async {
640	        token.cancelled().await;
641	        tokio::time::sleep(grace).await;
642	    };
643	    tokio::select! {
644	        biased;
645	        result = attempt => result.unwrap_or(Err(ExecutionError::Timeout { elapsed_ms: millis(limit) })),
646	        () = interrupted => Err(ExecutionError::Interrupted { elapsed_ms: millis(start.elapsed()) }),
647	    }
648	}
