650	/// Admission, the retry loop and classification for one step.
651	/// Saves the step's in-flight marker on a blocking thread, so a slow save (file or database I/O) ties up neither the
652	/// scheduler nor the other steps. The step waits for it: nothing of the step runs until this returns `Ok`.
653	async fn record_start(durable: Arc<dyn crate::DurableObserver>, job: &Job) -> Result<(), String> {
654	    let (run_id, step_id) = (job.run_id.clone(), job.step_id.clone());
655	    // AssertUnwindSafe: the observer is caller code and the scheduler's own state is not reachable from it.
656	    let saved = tokio::task::spawn_blocking(move || {
657	        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| durable.record_start(&run_id, &step_id)))
658	    })
659	    .await;
660	    match saved {
661	        Ok(Ok(result)) => result,
662	        Ok(Err(payload)) => {
663	            job.start_panicked.store(true, Ordering::Release);
664	            Err(format!("record_start panicked: {}", panic_message(payload.as_ref())))
665	        }
666	        // The blocking pool shut down under us (the runtime is being dropped).
667	        Err(join_err) => Err(format!("record_start did not finish: {join_err}")),
668	    }
669	}
