671	async fn run_step(job: Job) -> Outcome {
672	    if job.token.is_cancelled() {
673	        return Outcome {
674	            status: StepStatus::Skipped(SkipReason::Cancelled),
675	            error: None,
676	            reason: Some("run cancelled before the step started".to_string()),
677	        };
678	    }
679	    if let Some(durable) = job.durable.clone() {
680	        if let Err(reason) = record_start(durable, &job).await {
681	            return Outcome {
682	                status: StepStatus::NotRun(NotRunReason::StartNotRecorded),
683	                error: None,
684	                reason: Some(format!("its start could not be recorded, so it was not run: {reason}")),
685	            };
686	        }
687	    }
688	    let guard = match &job.breaker {
689	        Some((key, breaker)) => match breaker.admit() {
690	            Ok(admission) => Some(AdmissionGuard::new(Arc::clone(breaker), admission)),
691	            Err(err) => {
692	                return Outcome {
693	                    status: StepStatus::NotRun(NotRunReason::CircuitOpen),
694	                    reason: Some(format!("circuit breaker {key}: {err}")),
695	                    error: Some(err),
696	                }
697	            }
698	        },
699	        None => None,
700	    };
701	    let probe = guard.as_ref().is_some_and(AdmissionGuard::is_probe);
702	    let started = Instant::now();
703	    // A deadline too far away for the clock to represent is no deadline, rather than an overflow panic. With a
704	    // deadline group as well, the earlier end applies, and the reason names the one that did.
705	    let own = job.deadline.and_then(|d| started.checked_add(d));
706	    let (deadline, deadline_name) = match (own, &job.group_deadline) {
707	        (Some(own), Some((group, _))) if own <= *group => (Some(own), "step deadline".to_string()),
708	        (_, Some((group, key))) => (Some(*group), format!("deadline group {key}")),
709	        (own, None) => (own, "step deadline".to_string()),
710	    };
711	    let limit_from = |now: Instant| match deadline {
712	        Some(d) => job.attempt_timeout.min(d.saturating_duration_since(now)).max(Duration::from_millis(1)),
713	        None => job.attempt_timeout,
714	    };
715	    // A deadline-bound step's attempt runs until its deadline, not the attempt timeout; without a deadline it falls
716	    // back to the timeout.
717	    let attempt_limit_from = |now: Instant| match (job.bound, deadline) {
718	        (AttemptBound::Deadline, Some(d)) => d.saturating_duration_since(now).max(Duration::from_millis(1)),
719	        _ => limit_from(now),
720	    };
721	    let mut attempt = 0u32;
722	    // The last failed attempt's error, which decides the outcome when a later precheck cannot run the step again.
723	    let mut prior: Option<ExecutionError> = None;
724	    let (err, stop) = loop {
725	        let ctx =
726	            StepContext::for_attempt(job.run_id.clone(), job.step_id.clone(), attempt, job.token.clone(), deadline);
727	        if job.replay == Replay::Prechecked {
728	            let now = Instant::now();
729	            let limit = limit_from(now);
730	            let ctx = ctx.clone().bounded(now.checked_add(limit), job.attempt_timeout);
731	            let checked = precheck_once(job.runner.as_ref(), &ctx, limit, &job.token, job.grace).await;
732	            let not_runnable = match checked {
733	                Checked::NotApplied if !job.token.is_cancelled() => None,
734	                Checked::Applied => {
735	                    if let Some(err) = &prior {
736	                        report_failure(guard, err);
737	                    }
738	                    return Outcome {
739	                        status: StepStatus::CompletedEarlier,
740	                        error: None,
741	                        reason: Some("already applied (precheck)".to_string()),
742	                    };
743	                }
744	                Checked::NotApplied => Some("run cancelled".to_string()),
745	                Checked::Unknown(why) => Some(why),
746	                Checked::Refused(refusal) => match prior {
747	                    // An earlier attempt may have taken effect: the refusal cannot clear that doubt.
748	                    Some(err) if err.effect() == Effect::Unknown => {
749	                        break (err, format!("the precheck refused to continue: {refusal}"));
750	                    }
751	                    _ => {
752	                        let reason = format!("precheck: {refusal}");
753	                        return Outcome { status: StepStatus::Failed, error: Some(refusal), reason: Some(reason) };
754	                    }
755	                },
756	            };
757	            if let Some(why) = not_runnable {
758	                match prior {
759	                    Some(err) => break (err, format!("{why}, so the step was not tried again after this attempt")),
760	                    None if job.token.is_cancelled() => {
761	                        return Outcome {
762	                            status: StepStatus::Skipped(SkipReason::Cancelled),
763	                            error: None,
764	                            reason: Some("run cancelled before the step started".to_string()),
765	                        };
766	                    }
767	                    None => {
768	                        return Outcome {
769	                            status: StepStatus::NotRun(NotRunReason::Unverified),
770	                            error: None,
771	                            reason: Some(format!(
772	                                "{why}: whether the effect is already in place is unknown, so the step was not run"
773	                            )),
774	                        };
775	                    }
776	                }
777	            }
778	        }
779	        let attempt_start = Instant::now();
780	        let limit = attempt_limit_from(attempt_start);
781	        let ctx = ctx.bounded(attempt_start.checked_add(limit), job.attempt_timeout);
782	        let result = attempt_once(job.runner.as_ref(), &ctx, limit, &job.token, job.grace).await;
783	        lock(&job.attempts).push(AttemptRecord {
784	            attempt,
785	            class: result.as_ref().err().map(ExecutionError::replay_class),
786	            error: result.as_ref().err().map(ToString::to_string),
787	            elapsed: attempt_start.elapsed(),
788	        });
789	        let err = match result {
790	            Ok(()) => {
791	                if let Some(budget) = &job.budget {
792	                    lock(budget).deposit();
793	                }
794	                if let Some(guard) = guard {
795	                    guard.complete(true);
796	                }
797	                return Outcome { status: StepStatus::Completed, error: None, reason: None };
798	            }
799	            Err(err) => err,
800	        };
801	        if job.token.is_cancelled() {
802	            break (err, "run cancelled".to_string());
803	        }
804	        if !may_reinvoke(job.replay, &err) {
805	            break (err, String::new());
806	        }
807	        if probe {
808	            break (err, "a half-open breaker allows one probe attempt".to_string());
809	        }
810	        // A server's hint is honoured past `max_delay` but not without limit: a day-long `Retry-After` would park the
811	        // run. The step ends with this error as it is; resume runs it again if it is safe to.
812	        if let Some(hint) = err.retry_after().filter(|hint| *hint > job.retry_after_cap) {
813	            let stop = format!(
814	                "the server's retry hint of {}ms exceeded the retry-after cap of {}ms, so it was not waited for",
815	                millis(hint),
816	                millis(job.retry_after_cap)
817	            );
818	            break (err, stop);
819	        }
820	        let seed = job.jitter_seed.unwrap_or_else(|| derived_jitter_seed(&job.run_id, &job.step_id, attempt));
821	        let Some(delay) = retry_delay(&job.retry, attempt, seed, err.retry_after()) else {
822	            break (err, "retries exhausted".to_string());
823	        };
824	        if deadline.is_some_and(|d| Instant::now().checked_add(delay).is_none_or(|wake| wake >= d)) {
825	            break (err, format!("{deadline_name} reached"));
826	        }
827	        if let Some(budget) = &job.budget {
828	            if !lock(budget).try_withdraw() {
829	                break (err, "retry budget exhausted".to_string());
830	            }
831	        }
832	        let cancelled = tokio::select! {
833	            () = tokio::time::sleep(delay) => false,
834	            () = job.token.cancelled() => true,
835	        };
836	        if cancelled {
837	            break (err, "run cancelled during backoff".to_string());
838	        }
839	        attempt += 1;
840	        prior = Some(err);
841	    };
842	    report_failure(guard, &err);
843	    classify(err, job.replay, &stop, job.token.is_cancelled())
844	}
