853	/// The backoff before retry `attempt + 1`: michi-core's [`next_retry_delay`], except that a server's `retry_after` is
854	/// honoured in full even past `RetryConfig::max_delay`, which caps only the exponential backoff. The step's deadline
855	/// (its own or its group's) still bounds it: the caller stops retrying if the wait would end past the deadline.
856	fn retry_delay(retry: &RetryConfig, attempt: u32, seed: f64, retry_after: Option<Duration>) -> Option<Duration> {
857	    let backoff = next_retry_delay(retry, attempt, seed, retry_after)?;
858	    Some(retry_after.map_or(backoff, |hint| backoff.max(ceil_to_millis(hint))))
859	}
