862	fn ceil_to_millis(d: Duration) -> Duration {
863	    let whole = Duration::from_millis(millis(d));
864	    if whole < d {
865	        whole.saturating_add(Duration::from_millis(1))
866	    } else {
867	        whole
868	    }
869	}
