871	/// A jitter seed in `[0, 1)` for one retry, derived from the run id, step id and attempt: steps that fail together
872	/// back off by different amounts, and the same run always waits the same delays.
873	fn derived_jitter_seed(run_id: &RunId, step_id: &StepId, attempt: u32) -> f64 {
874	    let mut h = Fnv::new();
875	    h.write(run_id.as_str().as_bytes());
876	    h.write(b":");
877	    h.write(step_id.as_str().as_bytes());
878	    h.write(b":");
879	    h.write(&attempt.to_le_bytes());
880	    // FNV-1a mixes its last bytes poorly; the splitmix64 finalizer spreads them over every bit.
881	    let mut z = h.finish();
882	    z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
883	    z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
884	    z ^= z >> 31;
885	    // The top 53 bits as a fraction of 2^53, both exact in an f64.
886	    #[allow(clippy::cast_precision_loss, reason = "53-bit values fit an f64 mantissa exactly")]
887	    let fraction = (z >> 11) as f64 / (1u64 << 53) as f64;
888	    fraction
889	}
