891	/// The terminal status and final error for a step whose last attempt failed with `err`. `cancelled` says whether the
892	/// step's cancellation token had fired. A step that returns [`ExecutionError::Cancelled`] while the token had not
893	/// fired stopped on its own, so it ends `Failed`: a root cause that resume runs again, not a `Skipped(Cancelled)`
894	/// consequence.
895	///
896	/// An error whose effect is unknown ends a step that is not idempotent `OutcomeUnknown`, wrapped in
897	/// [`ExecutionError::AmbiguousOutcome`], so resume holds it (or, for a prechecked step, runs its precheck) instead of
898	/// repeating an effect that may have landed. An idempotent step ends `Failed` with the error as it is.
899	fn classify(err: ExecutionError, replay: Replay, stop: &str, cancelled: bool) -> Outcome {
900	    let mut stop = stop;
901	    let (status, error) = match err.replay_class() {
902	        ReplayClass::NotExecuted => match err.innermost() {
903	            ExecutionError::CircuitOpen { .. } => (StepStatus::NotRun(NotRunReason::CircuitOpen), err),
904	            _ if cancelled => (StepStatus::Skipped(SkipReason::Cancelled), err),
905	            _ => {
906	                if stop.is_empty() {
907	                    stop = "the step cancelled itself although the run was not cancelled";
908	                }
909	                (StepStatus::Failed, err)
910	            }
911	        },
912	        _ if err.effect() == Effect::Unknown && replay != Replay::Idempotent => {
913	            let cause = match err.innermost() {
914	                ExecutionError::Http { status: 502 | 504, .. } => UnknownCause::Gateway,
