use std::num::NonZeroUsize;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

use michi_pipeline::{
    execute, step_fn, CancellationToken, DurableObserver, ExecOptions, ExecStep, ExecutionError, FailurePolicy, Mode,
    Plan, RunId, StepId, StepObserver, StepRecord,
};

fn id(s: &str) -> StepId { StepId::try_new(s).expect("id") }

struct Store;
impl StepObserver for Store { fn on_step_finished(&self, _: &RunId, _: &StepRecord) {} }
impl DurableObserver for Store {
    fn record_start(&self, _: &RunId, step: &StepId) -> Result<(), String> {
        if step.as_str() == "b" { std::thread::sleep(Duration::from_millis(200)); }
        Ok(())
    }
}

fn plan(invoked: Arc<AtomicBool>) -> Plan {
    let a = ExecStep::new(id("a"), "a", step_fn(|_| async { Err(ExecutionError::failed("boom")) }));
    let b = ExecStep::new(id("b"), "b", step_fn(move |_| {
        invoked.store(true, Ordering::SeqCst);
        async { tokio::time::sleep(Duration::from_millis(50)).await; Ok(()) }
    }));
    Plan::new(vec![a, b]).expect("plan")
}

#[tokio::test(flavor = "multi_thread")]
async fn fail_fast_during_save() {
    let invoked = Arc::new(AtomicBool::new(false));
    let p = plan(Arc::clone(&invoked));
    let opts = ExecOptions::new()
        .mode(Mode::Parallel { max_concurrency: NonZeroUsize::new(2).expect("nz") })
        .failure_policy(FailurePolicy::FailFast)
        .cancel_grace(Duration::from_millis(10))
        .durable_starts(Arc::new(Store));
    let rec = execute(&p, RunId::try_new("r").expect("id"), &opts).await;
    for s in rec.steps() { eprintln!("{} {:?} {:?}", s.step_id(), s.status(), s.reason()); }
    eprintln!("b invoked after fail-fast: {}", invoked.load(Ordering::SeqCst));
    assert!(!invoked.load(Ordering::SeqCst), "b's effect ran after the run was stopped");
}

#[tokio::test(flavor = "multi_thread")]
async fn external_cancel_during_save() {
    let invoked = Arc::new(AtomicBool::new(false));
    let inv = Arc::clone(&invoked);
    let b = ExecStep::new(id("b"), "b", step_fn(move |_| {
        inv.store(true, Ordering::SeqCst);
        async { Ok(()) }
    }));
    let p = Plan::new(vec![b]).expect("plan");
    let token = CancellationToken::new();
    let t2 = token.clone();
    tokio::spawn(async move { tokio::time::sleep(Duration::from_millis(50)).await; t2.cancel(); });
    let opts = ExecOptions::new().cancellation(token).cancel_grace(Duration::from_millis(10)).durable_starts(Arc::new(Store));
    let rec = execute(&p, RunId::try_new("r").expect("id"), &opts).await;
    for s in rec.steps() { eprintln!("{} {:?} {:?}", s.step_id(), s.status(), s.reason()); }
    assert!(!invoked.load(Ordering::SeqCst), "b's effect ran after the run was cancelled");
}
EOF
